import { FC } from "react";
import { useFormik } from "formik";
import Select from "react-select";
import { Category, Product } from "@/types/product";

interface FormDetailsProps {
  productData: Product;
}

const FormDetails: FC<FormDetailsProps> = ({ productData }) => {
  const formik = useFormik({
    initialValues: {
      productName: productData.productName || "",
      detail: productData.detail || "",
      price: productData.price || "",
      weight: productData.weight || "",
      productCategory: productData.categoryId ? String(productData.categoryId) : "",
    },
    enableReinitialize: true,
    validationSchema,
    onSubmit: async (values) => {
      // Add submit logic here
    }
  });

  return (
    <form onSubmit={formik.handleSubmit} className="space-y-6">
      {/* Product Name */}
      <div>
        <label className="block text-gray-700 font-medium mb-1">Product Name</label>
        <input
          type="text"
          className="w-full p-3 border rounded-lg text-gray-700 focus:ring-2 focus:ring-blue-400 focus:outline-none"
          {...formik.getFieldProps("productName")}
        />
        {formik.touched.productName && formik.errors.productName && (
          <div className="text-red-500 text-sm mt-1">{formik.errors.productName}</div>
        )}
      </div>

      {/* Category */}
      <div>
        <label className="block text-gray-700 font-medium mb-1">Category</label>
        <Select
          options={categoryData?.content?.map((cat: Category) => ({
            value: cat.categoryId,
            label: cat.categoryName,
          })) || []}
          value={
            categoryData?.content
              ?.map((cat: { categoryId: any; categoryName: any }) => ({
                value: cat.categoryId,
                label: cat.categoryName,
              }))
              ?.find((option: { value: number }) => option.value === Number(formik.values.productCategory)) || null
          }
          onChange={(selectedOption) => {
            formik.setFieldValue("productCategory", selectedOption?.value || "");
            formik.setTouched({ ...formik.touched, productCategory: true });
          }}
          isSearchable
          isDisabled={!categoryData?.content}
          className="text-gray-700 w-full md:w-3/4"
        />
      </div>

      {/* Add other fields for detail, price, weight */}
    </form>
  );
};

export default FormDetails;